// ---------------------------------------------------------------------------
// qr_blk: ONE BLOCK per matrix, WHOLE n x n matrix resident in smem, RIGHT-
// LOOKING BLOCKED Householder QR done entirely on-chip in a SINGLE launch.
//
// Distinct from qr_small (which is UNBLOCKED -- n serial rank-1 trailing updates,
// BLAS-2, ~600 block syncs for n=176 -> 1065us). qr_blk processes the matrix in
// BLK-wide panels: each panel is factored serially in smem (BLK steps over the
// BLK-wide strip only), then ONE blocked WY trailing update
//   A_trail -= V @ (T^T @ (V^T @ A_trail))
// is applied to all remaining columns at once (BLAS-3, fully parallel across the
// block's threads, ~3 syncs per panel). For n=176 that is 6 panels -> ~18 syncs
// total vs ~600 for qr_small, and the bulk FLOPs are a parallel GEMM instead of a
// serial rank-1 chain. Everything stays in smem: A is loaded once, factored in
// place, written once -- NO HBM round-trips of A/V/T/H between panels (the multi-
// launch Triton path re-reads A from HBM on every panel + every trailing sweep).
//
// All arithmetic is plain fp32 (full-precision FMAs, MORE accurate than the
// Triton path's tf32x3 tensor-core GEMMs), so the LAPACK QR invariants hold for
// the dense well-conditioned n=176 benchmark with margin.
//
// Smem layout (floats), all column-major where 2D:
//   sA  : n*n      whole matrix (sA[c*n+r] = element (r,c))
//   sV  : n*BLK    panel reflectors V (sV[k*n+r] = v_k[r], unit-lower)
//   sT  : BLK*BLK  WY T factor (upper-tri), sT[c*BLK+r]
//   sW  : BLK*WCH  trailing W = V^T@A_trail chunk scratch (WCH cols at a time)
//   sred: NW       per-warp reduction scratch
//   sv1 : BLK      per-step reflector tail scalars / w broadcast
// Convention bit-identical to LAPACK dlarfg / torch.geqrf (matches qr_small).
// ---------------------------------------------------------------------------
extern "C" __global__ void qr_blk(
    const float* __restrict__ Ain,   // (B, n, n) row-major
    float* __restrict__ Hout,        // (B, n, n) row-major
    float* __restrict__ tauout,      // (B, n)
    int B, int n, int BLK)
{
    extern __shared__ float smem[];
    const int bid = blockIdx.x;
    if (bid >= B) return;
    const int tid = threadIdx.x;
    const int NT = blockDim.x;
    const int lane = tid & 31;
    const int warp = tid >> 5;
    const int nwarps = (NT + 31) >> 5;

    float* sA = smem;                       // n*n
    float* sV = sA + (long)n * n;           // n*BLK
    float* sT = sV + (long)n * BLK;         // BLK*BLK
    float* sred = sT + (long)BLK * BLK;     // nwarps (>=1)
    float* svw = sred + 32;                 // BLK (tau / w broadcast)

    const float* Ab = Ain + (long)bid * n * n;
    float* Hb = Hout + (long)bid * n * n;
    float* taub = tauout + (long)bid * n;

    // Load A (row-major HBM) -> sA (column-major smem). (r,c): HBM r*n+c -> c*n+r.
    for (long idx = tid; idx < (long)n * n; idx += NT) {
        int r = idx / n;
        int c = idx - r * n;
        sA[(long)c * n + r] = Ab[idx];
    }
    __syncthreads();

    for (int j = 0; j < n; j += BLK) {
        int b = min(BLK, n - j);            // panel width
        int h = n - j;                      // panel height (rows j..n-1)

        // ---- PANEL FACTOR: serial over the b columns of the panel [j, j+b) ----
        // Work on sA columns (j..j+b-1), rows (j..n-1). Build sV (unit-lower
        // reflectors, indexed v_k[r] for global row r) and sT incrementally.
        for (int kk = 0; kk < b; ++kk) {
            int gk = j + kk;                // global column / pivot row
            float* col = sA + (long)gk * n; // column gk (column-major contiguous)
            float alpha = col[gk];

            // tail2 = sum_{r=gk+1..n-1} col[r]^2
            float part = 0.0f;
            for (int r = gk + 1 + tid; r < n; r += NT) {
                float x = col[r];
                part += x * x;
            }
            #pragma unroll
            for (int off = 16; off > 0; off >>= 1)
                part += __shfl_down_sync(0xffffffffu, part, off);
            if (lane == 0) sred[warp] = part;
            __syncthreads();
            float tail2 = 0.0f;
            if (tid == 0) {
                for (int w = 0; w < nwarps; ++w) tail2 += sred[w];
                sred[0] = tail2;
            }
            __syncthreads();
            tail2 = sred[0];

            float beta, tau_k, scale;
            if (tail2 == 0.0f) { beta = alpha; tau_k = 0.0f; scale = 1.0f; }
            else {
                float normx = sqrtf(alpha * alpha + tail2);
                float sgn = (alpha >= 0.0f) ? 1.0f : -1.0f;
                beta = -sgn * normx;
                tau_k = (beta - alpha) / beta;
                scale = 1.0f / (alpha - beta);
            }

            // Build v into sV column kk: v[gk]=1, v[r>gk]=col[r]*scale, v[r<gk]=0.
            // Finalize column gk of R/H in sA: col[gk]=beta, col[r>gk]=v (reflector).
            float* vcol = sV + (long)kk * n;
            if (tid == 0) { col[gk] = beta; taub[gk] = tau_k; }
            for (int r = tid; r < n; r += NT) {
                float vr;
                if (r < gk) vr = 0.0f;
                else if (r == gk) vr = 1.0f;
                else { vr = col[r] * scale; col[r] = vr; }
                vcol[r] = vr;
            }
            __syncthreads();

            // Apply H_k to the rest of THIS panel's columns c in (gk+1, j+b):
            //   w[c] = v_k . A[:,c];  A[:,c] -= tau_k * v_k * w[c]
            // (BLAS-2 within the narrow panel only.)
            if (tau_k != 0.0f) {
                for (int c = gk + 1 + warp; c < j + b; c += nwarps) {
                    const float* cc = sA + (long)c * n;
                    float acc = 0.0f;
                    for (int r = gk + lane; r < n; r += 32)
                        acc += vcol[r] * cc[r];
                    #pragma unroll
                    for (int off = 16; off > 0; off >>= 1)
                        acc += __shfl_down_sync(0xffffffffu, acc, off);
                    if (lane == 0) svw[c - (j)] = tau_k * acc;  // park (rel index)
                }
                __syncthreads();
                // A[r,c] -= v[r] * (tau*w[c]) over the panel trailing tile
                for (int c = gk + 1; c < j + b; ++c) {
                    float twc = svw[c - j];
                    float* cc = sA + (long)c * n;
                    for (int r = gk + tid; r < n; r += NT)
                        cc[r] -= vcol[r] * twc;
                }
                __syncthreads();
            }

            // ---- incremental WY T factor (LAPACK dlarft forward) ----
            // T[0:kk,kk] = -tau_k * T[0:kk,0:kk] * (V[:,0:kk]^T v_k);  T[kk,kk]=tau_k.
            // z[i] = V[:,i] . v_k for i<kk  (one warp per i).
            if (tau_k == 0.0f) {
                for (int i = tid; i <= kk; i += NT)
                    sT[(long)kk * BLK + i] = (i == kk) ? 0.0f : 0.0f;
                __syncthreads();
            } else {
                for (int i = warp; i < kk; i += nwarps) {
                    const float* vi = sV + (long)i * n;
                    float acc = 0.0f;
                    for (int r = gk + lane; r < n; r += 32)   // v_k supported on r>=gk
                        acc += vi[r] * vcol[r];
                    #pragma unroll
                    for (int off = 16; off > 0; off >>= 1)
                        acc += __shfl_down_sync(0xffffffffu, acc, off);
                    if (lane == 0) svw[i] = acc;              // z[i] in svw[0..kk-1]
                }
                __syncthreads();
                // T[:,kk] = -tau_k * (T[:,0:kk] @ z); diag = tau_k.
                for (int i = tid; i <= kk; i += NT) {
                    if (i == kk) { sT[(long)kk * BLK + kk] = tau_k; continue; }
                    float acc = 0.0f;
                    for (int p = i; p < kk; ++p)              // T upper-tri: rows<=p
                        acc += sT[(long)p * BLK + i] * svw[p];
                    sT[(long)kk * BLK + i] = -tau_k * acc;
                }
                __syncthreads();
            }
        } // end panel columns

        // ---- BLOCKED WY TRAILING UPDATE over columns [j+b, n) ----
        //   A_trail -= V @ (T^T @ (V^T @ A_trail))
        // V is (h x b) supported on rows [j,n) (sV columns 0..b-1, unit-lower).
        int jb = j + b;
        int ncols = n - jb;
        if (ncols > 0) {
            // Process trailing columns in chunks of WCH (=BLK) to bound sW. For
            // each chunk: W = V^T@A (b x wch), Y = T^T@W (b x wch), A -= V@Y.
            float* sW = svw;  // reuse: need b*WCH; but svw is only BLK -> allocate
            // We size sW as part of sV-adjacent region instead. Use a local
            // chunk loop with W kept in smem region right after sT scratch is
            // free. Simpler: reuse sA-free? No. Use dedicated sW after svw.
            float* sWchunk = svw + BLK;          // b * BLK floats (chunk W/Y)
            for (int c0 = jb; c0 < n; c0 += BLK) {
                int wch = min(BLK, n - c0);
                // W[k, c] = sum_{r in [j,n)} V[r,k] * A[r, c0+c]   (k<b, c<wch)
                // one warp per (k) row of W? -> parallelize over (k,c) flat.
                for (int idx = warp; idx < b * wch; idx += nwarps) {
                    int kc = idx / wch;          // 0..b-1
                    int cc = idx - kc * wch;     // 0..wch-1
                    const float* vk = sV + (long)kc * n;
                    const float* ac = sA + (long)(c0 + cc) * n;
                    float acc = 0.0f;
                    for (int r = j + lane; r < n; r += 32)
                        acc += vk[r] * ac[r];
                    #pragma unroll
                    for (int off = 16; off > 0; off >>= 1)
                        acc += __shfl_down_sync(0xffffffffu, acc, off);
                    if (lane == 0) sWchunk[kc * BLK + cc] = acc;
                }
                __syncthreads();
                // Y[k,c] = sum_{p>=k} T[k,p] * W[p,c]   (T upper-tri, T^T@W).
                // Overwrite into a second region to avoid races: reuse sWchunk
                // after copying? Compute Y in registers per element into sV-free?
                // We compute Y in place is unsafe (Y[k] needs W[p>=k]); compute
                // top-down is fine because Y[k] only needs W[p>=k] which are not
                // yet overwritten if we go k = b-1 .. 0. Do k descending.
                for (int idx = tid; idx < b * wch; idx += NT) {
                    int kc = idx / wch;
                    // map to descending k to keep W[p>=k] intact: process kc' = b-1-kc
                    int k = b - 1 - kc;
                    int cc = idx - kc * wch;
                    float acc = 0.0f;
                    for (int p = k; p < b; ++p)
                        acc += sT[(long)p * BLK + k] * sWchunk[p * BLK + cc];
                    __syncthreads();   // ensure all reads of row k done before write
                    sWchunk[k * BLK + cc] = acc;
                    __syncthreads();
                }
                // A[r, c0+c] -= sum_k V[r,k] * Y[k,c]   over rows [j,n)
                for (int idx = tid; idx < h * wch; idx += NT) {
                    int rr = idx / wch;          // 0..h-1
                    int cc = idx - rr * wch;     // 0..wch-1
                    int r = j + rr;
                    float acc = 0.0f;
                    for (int k = 0; k < b; ++k)
                        acc += sV[(long)k * n + r] * sWchunk[k * BLK + cc];
                    sA[(long)(c0 + cc) * n + r] -= acc;
                }
                __syncthreads();
            }
        }
    } // end panels

    // Write H back (column-major smem -> row-major HBM).
    for (long idx = tid; idx < (long)n * n; idx += NT) {
        int r = idx / n;
        int c = idx - r * n;
        Hb[idx] = sA[(long)c * n + r];
    }
}


